from typing import List

def asteroid_game(size: List[int], direction: List[int]) -> List[int]:
    stack = []                      # (size, direction)
    for s, d in zip(size, direction):
        alive = True
        while alive and d == 0 and stack and stack[-1][1] == 1:
            top = stack[-1][0]
            if top <= s:
                stack.pop()
            if top >= s:
                alive = False
        if alive:
            stack.append((s, d))
    return [s for s, _ in stack]
